import { readFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const sourcePath = "config/content-radar-sources.json";
const config = JSON.parse(await readFile(join(repoRoot, sourcePath), "utf8"));
const seeds = Array.isArray(config.listeningSeeds) ? config.listeningSeeds.map(normalizeSeed).filter(Boolean) : [];
const now = "2026-07-10T00:00:00.000Z";

const statements = [
  "-- Generated by scripts/generate-social-listening-seed-sql.mjs",
  "-- Apply only to the LWT Supabase project: udqjdegsqxfvaocuuvab",
  "begin;",
  ...seeds.flatMap(upsertSourceItemSql),
  ...seeds.flatMap(upsertContentIdeaSql),
  ...upsertMemoryDocumentSql(buildAggregateMemoryDocument(seeds)),
  "commit;",
];

process.stdout.write(`${statements.join("\n\n")}\n`);

function normalizeSeed(input) {
  const topic = sanitizeText(input.topic, 180);
  const audienceQuestion = sanitizeText(input.audienceQuestion, 500);
  if (!topic || !audienceQuestion) return null;
  const priority = ["high", "medium", "low"].includes(input.priority) ? input.priority : "medium";
  return {
    topic,
    idSlug: slug(topic),
    priority,
    audienceQuestion,
    reactionThemes: sanitizeList(input.reactionThemes ?? []),
    objectionThemes: sanitizeList(input.objectionThemes ?? []),
    personalExperienceAngles: sanitizeList(input.personalExperienceAngles ?? []),
    popularStructurePatterns: sanitizeList(input.popularStructurePatterns ?? []),
    safeBlogAngles: sanitizeList(input.safeBlogAngles ?? []),
    relatedProducts: sanitizeList(input.relatedProducts ?? []),
    relatedCollections: sanitizeList(input.relatedCollections ?? []),
    sourceNote: sanitizeText(input.sourceNote ?? "manual curated public social listening summary", 240),
    sourceUrl: sanitizeText(input.sourceUrl ?? "", 500),
  };
}

function upsertSourceItemSql(seed) {
  const id = `source_manual_listening_${seed.idSlug}_20260710`;
  const excerpt = socialListeningExcerpt(seed);
  const scoreJson = {
    source: "curated_social_listening_seed",
    priority: seed.priority,
    audienceQuestion: seed.audienceQuestion,
    reactionThemes: seed.reactionThemes,
    objectionThemes: seed.objectionThemes,
    personalExperienceAngles: seed.personalExperienceAngles,
    popularStructurePatterns: seed.popularStructurePatterns,
    safeBlogAngles: seed.safeBlogAngles,
    relatedProducts: seed.relatedProducts,
    relatedCollections: seed.relatedCollections,
    sourceBatch: "2026-07-10",
  };
  return [
    `insert into source_items (
  id, source, source_url, source_author_or_subreddit, title, text_excerpt,
  collected_at, score_json, raw_json
)
values (
  ${sqlString(id)},
  'manual',
  ${seed.sourceUrl ? sqlString(seed.sourceUrl) : "null"},
  ${sqlString(seed.sourceNote)},
  ${sqlString(`${seed.topic} - curated social listening`)},
  ${sqlString(excerpt)},
  ${sqlString(now)},
  ${sqlJson(scoreJson)},
  null
)
on conflict (id) do update set
  source = excluded.source,
  source_url = excluded.source_url,
  source_author_or_subreddit = excluded.source_author_or_subreddit,
  title = excluded.title,
  text_excerpt = excluded.text_excerpt,
  collected_at = excluded.collected_at,
  score_json = excluded.score_json,
  raw_json = excluded.raw_json;`,
  ];
}

function upsertContentIdeaSql(seed) {
  const id = `idea_social_listening_${seed.idSlug}_20260710`;
  const structure = seed.popularStructurePatterns[0] ?? "Question hook -> education -> checklist -> practitioner CTA";
  const sourceSummary = `curated social listening: ${seed.topic}; question: ${seed.audienceQuestion}; structure: ${structure}`;
  const suggestedTitle = titleCase(seed.safeBlogAngles[0] ?? `${seed.topic}: common questions before choosing wellness support`);
  const productTieIn = seed.relatedProducts.length
    ? `${seed.relatedProducts.join(", ")} and related LWT wellness categories`
    : `${seed.relatedCollections.join(", ") || "Related LWT wellness categories"} and practitioner-guided selection`;
  const risk = /glp-1|mthfr|dosage|medication/i.test(seed.topic) || /dosage|medication/i.test(seed.audienceQuestion) ? "Medium" : "Low";
  const complianceReason = risk === "Medium"
    ? "Use practitioner-guided educational framing and avoid medication, disease-treatment, or dosage directives."
    : "No high-risk medical claims detected in the summarized topic seed.";
  return [
    `insert into content_ideas (
  id, topic, source_summary, suggested_title, product_tie_in, compliance_risk,
  compliance_reason, safer_angle, suggested_cta, status, created_at
)
values (
  ${sqlString(id)},
  ${sqlString(seed.topic)},
  ${sqlString(sourceSummary)},
  ${sqlString(suggestedTitle)},
  ${sqlString(productTieIn)},
  ${sqlString(risk)},
  ${sqlString(complianceReason)},
  ${sqlString("Keep this educational and focused on practitioner-guided wellness support.")},
  ${sqlString("Explore practitioner-guided wellness support")},
  'idea',
  ${sqlString(now)}
)
on conflict (id) do update set
  topic = excluded.topic,
  source_summary = excluded.source_summary,
  suggested_title = excluded.suggested_title,
  product_tie_in = excluded.product_tie_in,
  compliance_risk = excluded.compliance_risk,
  compliance_reason = excluded.compliance_reason,
  safer_angle = excluded.safer_angle,
  suggested_cta = excluded.suggested_cta,
  status = excluded.status,
  created_at = excluded.created_at;`,
  ];
}

function buildAggregateMemoryDocument(inputSeeds) {
  const content = inputSeeds
    .map((seed) => [
      `Topic: ${seed.topic}`,
      `Question: ${seed.audienceQuestion}`,
      `Reactions: ${seed.reactionThemes.join("; ")}`,
      `Objections: ${seed.objectionThemes.join("; ")}`,
      `Personal experience angles: ${seed.personalExperienceAngles.join("; ")}`,
      `Popular structures: ${seed.popularStructurePatterns.join("; ")}`,
      `Safe blog angles: ${seed.safeBlogAngles.join("; ")}`,
    ].join("\n"))
    .join("\n\n");
  return {
    id: "memory_lwt_social_listening_blog_structure_20260710",
    sourceType: "market_signal",
    title: "LWT Social Listening Blog Structure Seed Pack",
    summary: "Curated public conversation patterns for LWT blog generation: audience questions, reactions, objections, personal-experience angles, and popular structure patterns.",
    content,
    metadata: {
      sourceBatch: "2026-07-10",
      sourcePath,
      source: "curated_social_listening_seed",
      rawCommentDumpsStored: false,
      accountCreationRequired: false,
    },
    relatedProducts: [...new Set(inputSeeds.flatMap((seed) => seed.relatedProducts))],
    relatedCollections: [...new Set(inputSeeds.flatMap((seed) => seed.relatedCollections))],
    evidenceLinks: [sourcePath, "docs/superpowers/specs/2026-07-10-social-listening-blog-feed-design.md"],
    sensitivity: "internal",
  };
}

function upsertMemoryDocumentSql(document) {
  const chunks = splitMemoryChunks([document.title, document.summary, document.content].join("\n"));
  return [
    `insert into agent_memory_documents (
  id, source_type, title, summary, content, metadata, related_products,
  related_collections, related_campaigns, evidence_links, sensitivity, updated_at
)
values (
  ${sqlString(document.id)},
  ${sqlString(document.sourceType)},
  ${sqlString(document.title)},
  ${sqlString(document.summary)},
  ${sqlString(document.content)},
  ${sqlJson(document.metadata)},
  ${sqlTextArray(document.relatedProducts)},
  ${sqlTextArray(document.relatedCollections)},
  array[]::text[],
  ${sqlJson(document.evidenceLinks)},
  ${sqlString(document.sensitivity)},
  now()
)
on conflict (id) do update set
  source_type = excluded.source_type,
  title = excluded.title,
  summary = excluded.summary,
  content = excluded.content,
  metadata = excluded.metadata,
  related_products = excluded.related_products,
  related_collections = excluded.related_collections,
  related_campaigns = excluded.related_campaigns,
  evidence_links = excluded.evidence_links,
  sensitivity = excluded.sensitivity,
  updated_at = now();`,
    `delete from agent_memory_chunks where document_id = ${sqlString(document.id)};`,
    `insert into agent_memory_chunks (id, document_id, chunk_index, content, embedding, embedding_model)
values
${chunks.map((chunk, index) => `  (${sqlString(`${document.id}_chunk_${index}`)}, ${sqlString(document.id)}, ${index}, ${sqlString(chunk)}, null, null)`).join(",\n")};`,
  ];
}

function socialListeningExcerpt(seed) {
  return [
    `Curated social listening for ${seed.topic}.`,
    `Audience question: ${seed.audienceQuestion}`,
    seed.reactionThemes.length ? `Reaction themes: ${seed.reactionThemes.join("; ")}` : "",
    seed.objectionThemes.length ? `Objections: ${seed.objectionThemes.join("; ")}` : "",
    seed.personalExperienceAngles.length ? `Personal-experience angles: ${seed.personalExperienceAngles.join("; ")}` : "",
    seed.popularStructurePatterns.length ? `Popular structure: ${seed.popularStructurePatterns.join("; ")}` : "",
    seed.safeBlogAngles.length ? `Safe blog angles: ${seed.safeBlogAngles.join("; ")}` : "",
  ].filter(Boolean).join(" ");
}

function sanitizeText(value, maxChars = 8000) {
  const redacted = String(value)
    .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, "[redacted-email]")
    .replace(/(?:\+?1[-.\s]?)?(?:\(?\d{3}\)?[-.\s]?)\d{3}[-.\s]?\d{4}/g, "[redacted-phone]")
    .replace(/\s+/g, " ")
    .trim();
  if (redacted.length <= maxChars) return redacted;
  return `${redacted.slice(0, Math.max(0, maxChars - 14)).trimEnd()} [truncated]`;
}

function sanitizeList(values) {
  return values.map((value) => sanitizeText(value, 700)).filter(Boolean);
}

function splitMemoryChunks(content, maxChunkChars = 1200) {
  const normalized = content.replace(/\s+/g, " ").trim();
  if (!normalized) return [];
  const chunks = [];
  let remaining = normalized;
  while (remaining.length > maxChunkChars) {
    const splitAt = findSplitPoint(remaining, maxChunkChars);
    chunks.push(remaining.slice(0, splitAt).trim());
    remaining = remaining.slice(splitAt).trim();
  }
  if (remaining) chunks.push(remaining);
  return chunks.slice(0, 25);
}

function findSplitPoint(value, maxChunkChars) {
  const window = value.slice(0, maxChunkChars);
  const sentence = Math.max(window.lastIndexOf(". "), window.lastIndexOf("? "), window.lastIndexOf("! "));
  if (sentence > maxChunkChars * 0.5) return sentence + 1;
  const space = window.lastIndexOf(" ");
  return space > maxChunkChars * 0.5 ? space : maxChunkChars;
}

function slug(value) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "").slice(0, 120);
}

function titleCase(value) {
  return value.replace(/\w\S*/g, (part) => part[0].toUpperCase() + part.slice(1).toLowerCase());
}

function sqlString(value) {
  return `'${String(value).replace(/'/g, "''")}'`;
}

function sqlJson(value) {
  return `${sqlString(JSON.stringify(value))}::jsonb`;
}

function sqlTextArray(values) {
  if (!values.length) return "array[]::text[]";
  return `array[${values.map(sqlString).join(", ")}]::text[]`;
}
